    /// CU-102 (b)'s `keys` sentences (none for auto_zoom, which zooms on clicks too).
    static func polishNeedsKeys(_ command: RecordingPolish.Command) -> String {
        let what = command == .speedUpTyping ? "typing to speed up" : "shortcut to show"
        return "\(command.rawValue): true needs keys: \"shortcuts\" — without it the cursor file "
            + "records no \(what)."
    }

    /// SERVER THREAD. CU-101 (j): for each command the choice asks for, in order, `decide`
    /// polled through `onMain` every `RecordingPolish.checkInterval`, then the tool's body; its
    /// answer object under the command's name, or a sentence under `<name>_error`. On `.drop`,
    /// `.giveUp` or the call's cancel, every command not yet run gets its sentence. The cursor
    /// files are read here, once, for the speed-up's readiness; a read that fails counts as
    /// ready, so the body says why.
    func polishLanded(
        _ result: RecordingResult, in document: ProjectDocument, into fields: inout [String: Any]
    ) {
        var remaining = RecordingPolish.commands(of: result.choice)
            // BEFORE `startCapture`, the header's own rule, so the first
            // sample lands in the file.
            try stream.addRecordingOutput(output)
        } catch {
            return refuse(
                .startFailed(
                    "The recording output could not be added: " + error.localizedDescription),
                completion)
        }
        // The cursor's capture and its segments' header (spec §11 CU-11, CU-13);
        // nothing runs until `launchScreen`.
        let cursor = CursorCapture()
        // Record shortcuts (CU-62): the key tap is made now, enabled with the poll.
        if choice.keys == .shortcuts, !cursor.makeKeyTap() {
            return refuse(.startFailed(RecordingGrant.inputMonitoringRefusal), completion)
        }
        let cursorStart = Self.cursorStart(filter: filter, choice: choice, stream: configs.stream)
        // The frame watch rides every screen recording (CU-13): E2 for a
        // camera, the geometry for the cursor. Only a camera's start needs it.
        var watch: ScreenFrameWatch?
        var watchLost: String?
        if ScreenFrameWatchRule.attaches(camera: camera != nil, cursor: true) {
            let made = ScreenFrameWatch(
                bound: ScreenFrameWatch.bound(rate: choice.rate),
                onGeometry: { [weak cursor] geometry, pts in cursor?.geometry(geometry, host: pts) })
            do {
                try stream.addStreamOutput(made, type: .screen, sampleHandlerQueue: made.queue)
                watch = made
            } catch {
                if ScreenFrameWatchRule.failsStart(camera: camera != nil) {
                    return refuse(
                        .startFailed(
                            "The screen's frames could not be watched: " + error.localizedDescription),
                        completion)
                }
                watch = nil
                return self.failStart(
                    error as? RecorderError ?? .cameraDevice(error.localizedDescription))
            }
            self.session?.camera?.note = capture.warmUp?.note
            self.launchScreen()
        }
    }

    /// MAIN THREAD, `.arming`: the one launch turn (CAM-9 (2)) — the
    /// microphone's file (when one was chosen), then the cursor's capture
    /// with segment 0 open (spec §11 CU-11), then the stream, then
    /// segment 0's camera writer (none without a camera). `startCapture`'s
    /// completion is `captureStarted`'s, which leaves `.arming`.
    func launchScreen() {
        guard state == .arming, let current = session else { return }
