    /// §11 SR-21 (c)); every other op (a trim, a reverse) writes none.
    static func paths(of ops: [ReelOp]) -> [String] {
        let groups = ["set_video": "video", "set_audio": "audio", "set_text": "text"]
        var found = Set<String>()
        for op in ops {
            if op.name == "set_speed" {
                found.insert("speed")
